/// 清除指定厂商的 API Key（keyring 条目按厂商名分存）；
/// 顺带把该厂商移出已验证名单（key 没了可用性随之失效）。
/// 两步必须同处 lock_config_write 之下——keyring 写在锁外做、配置写在锁内做，
/// 一旦中途 panic / 进程被杀，key 没了 verified_vendors 还在 → UI 绿点撒谎。
/// 顺序选「先 verified_vendors、再 keyring」：keyring 真失败可被上一句审计
/// 回滚（业务可接受：key 多留一段比「配置已标无效但 key 没了」更易恢复）。
#[tauri::command]
pub fn bot_clear_vendor_key(app: AppHandle, vendor: String) -> CommandResult<()> {
    let vendor = vendor.trim().to_string();
    if vendor.is_empty() {
        return Ok(());
    }
    super::io::update_config_file(&app, |cfg| {
        cfg.verified_vendors.retain(|v| v != &vendor);
    })?;
    keyring::delete_vendor_key(&vendor)
}

