/// 解析结果落库（单事务 + DB_WRITE_LOCK 与全库写路径互斥）；
/// 只覆盖 source='models_dev' 行（守卫在 upsert_*_sync 的 SQL 里）
pub fn apply_sync(
    conn: &mut rusqlite::Connection,
    providers: &[MetaProvider],
    models: &[MetaModel],
) -> Result<SyncStats, String> {
    let _g = crate::db::lock_db_write();
    let tx = conn.transaction().map_err(|e| e.to_string())?;
    for p in providers {
        super::upsert_provider_sync(&tx, p).map_err(|e| e.to_string())?;
    }
    for m in models {
        super::upsert_model_sync(&tx, m).map_err(|e| e.to_string())?;
    }
    tx.commit().map_err(|e| e.to_string())?;
    Ok(SyncStats {
        providers: providers.len(),
        models: models.len(),
    })
}

/// 手动触发 models.dev 同步（前端「更新模型库」按钮）：
/// 永远返回 Ok(MetaSyncResult)，失败时 ok:false + error，供按钮直接展示
#[tauri::command]
pub async fn meta_sync_models_dev(app: AppHandle) -> MetaSyncResult {
    match sync::sync_models_dev(&app).await {
        Ok(s) => MetaSyncResult {
            ok: true,
            providers: Some(s.providers),
            models: Some(s.models),
            error: None,
        },
        Err(e) => {
            crate::audit::write_event(
                &app,
                crate::audit::AuditLevel::Warn,
                "meta_sync_models_dev",
                &[("err", e.clone())],
            );
            MetaSyncResult {
                ok: false,
                providers: None,
                models: None,
                error: Some(e),
            }
        }
    }
}

